const {chromium}=require('playwright');const U='http://localhost:8765/';
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1280,height:1000}});const errs=[];p.on('pageerror',e=>errs.push(e.message));
const ok=(n,c)=>console.log((c?'PASS ':'FAIL ')+n);
await p.goto(U+'#/team');await p.evaluate(()=>{localStorage.clear();localStorage.setItem('kafila-entry','1');localStorage.setItem('screenpath-tour','{"open":false}');localStorage.setItem('screenpath-demo-ui','1')});await p.reload();await p.waitForTimeout(600);
const cnt=async()=>p.evaluate(()=>document.querySelector('[data-tab="mine"] .n').textContent);
const txt=async()=>p.locator('#view').innerText();
let t=await txt();ok('label View as',(await p.locator('label[for=role]').innerText())==='View as');
ok('coordinator intro',/You are Noura, coordinator/.test(t));const nc=await cnt();
await p.selectOption('#role','gp');await p.waitForTimeout(300);t=await txt();const ng=await cnt();
ok('gp intro + calls card',/You are Dr\. Hessa/.test(t)&&/Dr\. Hessa's calls today/.test(t)&&/Rajesh K\./.test(t));
await p.screenshot({path:'rv-gp.png'});
await p.selectOption('#role','specialist');await p.waitForTimeout(300);t=await txt();const ns=await cnt();
ok('specialist incoming',/Incoming/.test(t)&&/New referrals to accept or reject/.test(t));
await p.screenshot({path:'rv-sp.png'});
await p.selectOption('#role','lead');await p.waitForTimeout(400);ok('lead goes to dashboard',/#\/dashboard/.test(p.url())&&/You are Dr\. Khalid/.test(await txt()));
await p.goto(U+'#/team');await p.waitForTimeout(300);const nl=await cnt();
console.log('counts coord/gp/spec/lead',nc,ng,ns,nl);ok('counts differ per role',new Set([nc,ng,ns,nl]).size>=3);
await p.click('[data-tab="all"]');await p.waitForTimeout(200);ok('All cases reachable',/All cases/.test(await txt()));
console.log('errors',errs);await b.close()})();
